    ctx.lineTo(-6 * PS, -5 * PS);
    ctx.lineTo(0, -1 * PS);
    ctx.lineTo(7 * PS, -5 * PS);
    ctx.lineTo(14 * PS + sway, -2 * PS);
    ctx.lineTo(18 * PS + sway, -10 * PS);
    ctx.quadraticCurveTo(19 * PS, -31 * PS, 9 * PS, -43 * PS);
