    ctx.moveTo(-8.5 * PS, -42 * PS);
    ctx.lineTo(8.5 * PS, -42 * PS);
    ctx.lineTo(10 * PS, -18 * PS);
    ctx.quadraticCurveTo(0, -14 * PS, -10 * PS, -18 * PS);
