    ctx.fillStyle = '#152f2e';
    ctx.beginPath(); ctx.moveTo(-1 * PS, -62 * PS); ctx.lineTo(2 * PS, -67 * PS); ctx.lineTo(4 * PS, -61 * PS); ctx.closePath(); ctx.fill();
