        ctx.strokeStyle = k === 0 ? 'rgba(255,191,90,.1)' : k === 1 ? 'rgba(255,224,151,.25)' : 'rgba(255,252,231,.55)';
        ctx.lineWidth = (k === 0 ? 17 : k === 1 ? 8 : 2.2) * PS;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.arc(pos.x, pos.y - 29 * PS, arcR, Math.min(start, end), Math.max(start, end));
