        ctx.beginPath(); ctx.ellipse(0, 0, r * .7, r * .33, 0, 0, TAU); ctx.stroke();
        ctx.fillStyle = 'rgba(255,191,103,.28)';
        ctx.beginPath(); ctx.arc(0, 0, 2.2, 0, TAU); ctx.fill();
