    for (const b of G.braziers) {
      const pos = entPos(b);
      const fl = .82 + .18 * Math.sin(G.time * 6.3 + b.seed);
      const g = ctx.createRadialGradient(pos.x, pos.y - 20 * s, 0, pos.x, pos.y - 20 * s, 180 * s * fl);
