import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(runtime + '/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display','utf8').trim();
const browser = await chromium.launch({...cfg.browser.launchOptions, timeout: 30000});
async function measure(name, query, css='') {
  const page = await browser.newPage({viewport:{width:1280,height:800}});
  await page.goto('http://localhost:3000'+query,{waitUntil:'load'});
  await page.waitForTimeout(300);
  await page.locator('#start-button').click();
  if(css) await page.addStyleTag({content:css});
  const fps = await page.evaluate(() => new Promise(res => { let n=0; const t0=performance.now(); function f(){ n++; if(performance.now()-t0<2200) requestAnimationFrame(f); else res(n/((performance.now()-t0)/1000)); } requestAnimationFrame(f); }));
  console.log(name, fps.toFixed(2));
  await page.close();
}
const hide='#hud,.screen,.grain,.vignette,#damage-flash{display:none!important}';
for (const r of [1,.65,.4]) await measure('bg only res'+r, '?skip=walls,floor,decor,actors,particles,lights,barrier,projectiles&res='+r, hide);
for (const r of [1,.65]) await measure('full no UI res'+r, '?res='+r, hide);
for (const r of [1,.65]) await measure('full no UI no grain', '?res='+r, '#hud,.screen,.grain{display:none!important}');
await browser.close();

