import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(runtime + '/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display','utf8').trim();
const browser = await chromium.launch({...cfg.browser.launchOptions, timeout: 30000});
async function measure(name, query) {
  const page = await browser.newPage({viewport:{width:1280,height:800}});
  await page.goto('http://localhost:3000'+query,{waitUntil:'load'});
  await page.waitForTimeout(250);
  await page.locator('#start-button').click();
  await page.waitForTimeout(200);
  await page.addStyleTag({content:'#hud,.screen,.grain,.vignette,#damage-flash{display:none!important}'});
  const fps = await page.evaluate(() => new Promise(res => { let n=0; const t0=performance.now(); function f(){ n++; if(performance.now()-t0<2000) requestAnimationFrame(f); else res(n/((performance.now()-t0)/1000)); } requestAnimationFrame(f); }));
  console.log(name.padEnd(24), fps.toFixed(2));
  await page.close();
}
await measure('full', '?debug');
await measure('no lights', '?debug&skip=lights');
await measure('no particles', '?debug&skip=particles');
await measure('no decor', '?debug&skip=decor');
await measure('no walls', '?debug&skip=walls');
await measure('no floor', '?debug&skip=floor');
await measure('no effects', '?debug&skip=lights,particles,decor,barrier,projectiles');
await measure('bare', '?debug&skip=walls,floor,decor,actors,particles,lights,barrier,projectiles');
await browser.close();

