import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(runtime + '/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display','utf8').trim();
const browser = await chromium.launch({...cfg.browser.launchOptions, timeout: 30000});
async function shot(name, viewport, extra = ''){
  const context = await browser.newContext({ viewport, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
  const page = await context.newPage();
  page.on('pageerror', e => console.log('PAGEERROR', name, e.message));
  await page.goto('http://localhost:3000?debug'+extra, { waitUntil: 'load' });
  await page.waitForTimeout(1200);
  await page.screenshot({ path:`screenshots/${name}_title.jpg`, type:'jpeg', quality:86, timeout:60000 });
  await page.locator('#start-button').click();
  await page.waitForTimeout(2600);
