591:     if (keys.has('left')) x -= 1;
592:     if (keys.has('right')) x += 1;
593:     if (keys.has('up')) y -= 1;
594:     if (keys.has('down')) y += 1;
595:     const len = Math.hypot(x, y);
596:     return len ? { x: x / len, y: y / len, len: 1 } : { x: 0, y: 0, len: 0 };
597:   }
