618:     if (G.boss && ['chase', 'slamWindup', 'slamRecover', 'chargeWindup', 'chargeRecover', 'volleyWindup', 'volleyRecover', 'fissureWindup', 'fissureRecover'].includes(G.boss.state)) {
619:       const d = distEnt(p, G.boss);
620:       if (d < best) { best = d; target = G.boss; }
621:     }
622:     for (const w of G.wisps) {
623:       const d = distEnt(p, w);
624:       if (d < best) { best = d; target = w; }
625:     }
