import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(runtime + '/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display','utf8').trim();
const browser = await chromium.launch({...cfg.browser.launchOptions, timeout: 30000});
const context = await browser.newContext({ viewport:{width:1280,height:800} });
const page = await context.newPage();
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3000?debug', { waitUntil:'load' });
await page.waitForTimeout(600);
await page.locator('#start-button').click();
await page.waitForTimeout(300);

const check = (name, ok, detail) => console.log((ok?'PASS':'FAIL')+' '+name+(detail?' :: '+JSON.stringify(detail):''));

// --- chest / key ---
let r = await page.evaluate(() => {
  const E = window.__emberfall, G = E.G;
  G.player.x = G.chest.x; G.player.y = G.chest.y + .02;
  E.step(1/60, 2);
  const prompt = document.getElementById('interact-prompt').classList.contains('show');
  E.tryInteract();
  const after = { opening: G.chest.opening, progress: G.progress };
  E.step(1/60, 220);
  return { prompt, after, progress: G.progress, keyTaken: G.chest.keyTaken, keySlot: document.getElementById('key-slot').className, obj: document.getElementById('objective-text').textContent };
});
check('chest prompt appears', r.prompt, r);
check('chest opens', r.after.opening && r.after.progress === 'opening', r.after);
check('key acquired', r.keyTaken === true, { progress:r.progress, keySlot:r.keySlot });
check('objective -> unlock gate', /UNLOCK/i.test(r.obj), r.obj);

// --- gate unlock / boss awake ---
r = await page.evaluate(() => {
  const E = window.__emberfall, G = E.G;
  G.player.x = .5; G.player.y = G.gate.y + .05;
  E.step(1/60, 2);
  const prompt = document.getElementById('interact-prompt').classList.contains('show');
  E.tryInteract();
  const unlocking = G.gate.unlocking;
  E.step(1/60, 280);
  return { prompt, unlocking, open: G.gate.open, progress: G.progress, bossState: G.boss.state, bossUi: document.getElementById('boss-ui').classList.contains('show'), obj: document.getElementById('objective-text').textContent };
});
check('gate prompt appears', r.prompt, r);
check('gate unlocks on use', r.unlocking, r);
check('gate opens + boss wakes', r.open && r.progress === 'boss' && ['awaken','chase'].includes(r.bossState), r);
check('boss UI shows', r.bossUi, r.bossUi);
check('objective -> defeat boss', /DEFEAT/i.test(r.obj), r.obj);

// --- phases + victory ---
r = await page.evaluate(() => {
  const E = window.__emberfall, G = E.G;
  E.step(1/60, 140);
  G.player.inv = 99;
  const states = [];
  E.damageBoss(23, 'test');
  states.push({ hp:G.boss.hp, phase:G.boss.phase, state:G.boss.state });
  E.step(1/60, 100);
  E.damageBoss(23, 'test');
  states.push({ hp:G.boss.hp, phase:G.boss.phase, state:G.boss.state });
  E.step(1/60, 100);
  E.damageBoss(22, 'test');
  states.push({ hp:G.boss.hp, phase:G.boss.phase, state:G.boss.state });
  E.step(1/60, 200);
  return { states, state:G.state, progress:G.progress, endHidden:document.getElementById('end-screen').classList.contains('hidden'), endTitle:document.getElementById('end-title').textContent, endKicker:document.getElementById('end-kicker').textContent };
});
check('phase 2 at 2/3 hp', r.states[0].phase === 2, r.states[0]);
check('phase 3 at 1/3 hp', r.states[1].phase === 3, r.states[1]);
check('boss death -> victory', r.state === 'victory' && r.progress === 'won' && !r.endHidden, { state:r.state, progress:r.progress, endHidden:r.endHidden });
check('victory copy', /Warden Falls/i.test(r.endTitle), { title:r.endTitle, kicker:r.endKicker });

// --- replay + death ---
await page.locator('#replay-button').click();
await page.waitForTimeout(250);
r = await page.evaluate(() => {
  const E = window.__emberfall, G = E.G;
  E.step(1/60, 30);
  const started = { state:G.state, hp:G.player.hp, progress:G.progress, boss:G.boss.state };
  G.player.inv = 0;
  E.hurtPlayer(99);
  E.step(1/60, 140);
  return { started, state:G.state, endTitle:document.getElementById('end-title').textContent, endHidden:document.getElementById('end-screen').classList.contains('hidden'), endClass:document.getElementById('end-title').className };
});
check('replay resets run', r.started.state === 'playing' && r.started.progress === 'seek' && r.started.boss === 'dormant' && r.started.hp > 0, r.started);
check('player death -> ending', r.state === 'dead' && !r.endHidden && /Ashes/i.test(r.endTitle), { state:r.state, title:r.endTitle });
check('death styling', /fallen/.test(r.endClass), r.endClass);
check('no page errors', errors.length === 0, errors);

// --- touch controls ---
const tctx = await browser.newContext({ viewport:{width:390,height:844}, hasTouch:true, isMobile:true, deviceScaleFactor:2 });
const tp = await tctx.newPage();
const terrors = [];
tp.on('pageerror', e => terrors.push(e.message));
await tp.goto('http://localhost:3000?debug', { waitUntil:'load' });
await tp.waitForTimeout(800);
await tp.locator('#start-button').click();
await tp.waitForTimeout(400);
const touch = await tp.evaluate(async () => {
  const E = window.__emberfall, G = E.G;
  E.step(1/60, 40);
  const zone = document.getElementById('stick-zone');
  const b = zone.getBoundingClientRect();
  const x0 = b.left + b.width/2, y0 = b.top + b.height/2;
  const before = G.player.x;
  zone.dispatchEvent(new PointerEvent('pointerdown', {bubbles:true, pointerId:11, pointerType:'touch', clientX:x0, clientY:y0, isPrimary:true}));
  zone.dispatchEvent(new PointerEvent('pointermove', {bubbles:true, pointerId:11, pointerType:'touch', clientX:x0+42, clientY:y0, isPrimary:true}));
  E.step(1/60, 45);
  zone.dispatchEvent(new PointerEvent('pointerup', {bubbles:true, pointerId:11, pointerType:'touch', clientX:x0+42, clientY:y0, isPrimary:true}));
  const moved = G.player.x;
  G.player.attackCd = 0;
  document.getElementById('attack-btn').dispatchEvent(new PointerEvent('pointerdown', {bubbles:true, pointerId:12, pointerType:'touch', isPrimary:true}));
  const attacked = G.player.attackT > 0;
  return { before, moved, attacked, touchUi:getComputedStyle(document.getElementById('touch-ui')).display, touchClass:document.body.classList.contains('is-touch') };
});
check('touch UI visible', touch.touchUi === 'block' && touch.touchClass, touch);
check('joystick moves player', touch.moved > touch.before + .001, { before:touch.before, moved:touch.moved });
check('slash button attacks', touch.attacked, touch.attacked);
check('no touch-page errors', terrors.length === 0, terrors);
await tctx.close();
await browser.close();

