// core
const corePulse = .84 + Math.sin(t * 3.3) * .16 + (b.phase - 1) * .1;
ctx.save();
ctx.globalCompositeOperation = 'lighter';
glow(ctx, 0, -124, 42 * corePulse, b.phase >= 3 ? 'rgba(255,72,29,.65)' : 'rgba(255,114,37,.52)', 1);
ctx.restore();
ctx.fillStyle = '#231712';
ctx.beginPath(); ctx.arc(0, -124, 18, 0, TAU); ctx.fill();
ctx.strokeStyle = '#8f6d3c'; ctx.lineWidth = 3;
ctx.beginPath(); ctx.arc(0, -124, 17, 0, TAU); ctx.stroke();
const coreG = ctx.createRadialGradient(0, -124, 1, 0, -124, 12);
coreG.addColorStop(0, '#fff5ca');
coreG.addColorStop(.3, '#ffd173');
coreG.addColorStop(.7, '#f06b29');
coreG.addColorStop(1, '#7f1c11');
ctx.fillStyle = coreG;
ctx.beginPath(); ctx.arc(0, -124, 11.5 * corePulse, 0, TAU); ctx.fill();
// core prongs
for (let i = 0; i < 4; i++) {
  ctx.save(); ctx.rotate(i / 4 * TAU); ctx.fillStyle = '#6c5c44';
  ctx.beginPath(); ctx.moveTo(0, -34); ctx.lineTo(4, -23); ctx.lineTo(-4, -23); ctx.closePath(); ctx.fill(); ctx.restore();
}

