input.content:
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(runtime + '/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display','utf8').trim();
const browser = await chromium.launch({...cfg.browser.launchOptions, timeout: 30000});
async function run(name, viewport, opts={}) {
  const context = await browser.newContext({ viewport, hasTouch:!!opts.touch, isMobile:!!opts.touch, deviceScaleFactor:1 });
  const page = await context.newPage();
  await page.goto('http://localhost:3000?debug', { waitUntil:'load' });
  await page.waitForTimeout(800);
  await page.locator('#start-button').click();
  await page.waitForTimeout(900);
  // victory
  await page.evaluate(() => {
    const E = window.__emberfall, G = E.G;
    G.player.hp = 4;
    G.progress = 'won';
    G.boss.state = 'dying';
    G.boss.dying = 0;
    G.boss.hp = 0;
    document.getElementById('boss-ui').classList.remove('show');
    E.step(1/60, 190);
  });
  await page.waitForTimeout(600);
  await page.screenshot({ path:`/home/runner/work/PlayGround/PlayGround/screenshots/${name}_victory.jpg`, type:'jpeg', quality:88, timeout:60000 });
  // death on replay
  await page.locator('#replay-button').click();
  await page.waitForTimeout(500);
  await page.evaluate(() => {
    const E = window.__emberfall, G = E.G;
    G.player.inv = 0;
    E.hurtPlayer(99);
    E.step(1/60, 140);
  });
  await page.waitForTimeout(600);
  await page.screenshot({ path:`/home/runner/work/PlayGround/PlayGround/screenshots/${name}_death.jpg`, type:'jpeg', quality:88, timeout:60000 });
  console.log(name, 'done');
  await context.close();
}
await run('desktop', {width:1280,height:800});
await run('phone', {width:390,height:844}, {touch:true});
await run('landscape', {width:844,height:390}, {touch:true});
await browser.close();

