import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(runtime + '/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display','utf8').trim();
const browser = await chromium.launch({...cfg.browser.launchOptions, timeout: 30000});
const page = await browser.newPage({viewport:{width:1280,height:800}});
page.on('pageerror', e => console.log('ERR', e.message));
await page.goto('http://localhost:3000?debug', { waitUntil:'load' });
await page.waitForTimeout(600);
await page.locator('#start-button').click();
await page.waitForTimeout(900);
const info = await page.evaluate(() => {
  const E = window.__emberfall, G = E.G;
  G.chest.open = true; G.chest.openT = 1; G.chest.keyTaken = true;
  E.grantKey();
  G.gate.open = true; G.gate.unlocking = false; G.gate.t = 2;
  G.progress = 'boss';
  E.beginBossAwake();
  E.step(1/60, 140);
  G.boss.state = 'chase'; G.boss.t = 1; G.boss.cd = 99; G.boss.weapon = -.5;
  G.player.inv = 999; G.player.hp = 6;
  G.progress = 'boss';
  E.step(1/60, 200);
  G.boss.state = 'chase'; G.boss.cd = 99; G.boss.weapon = -.5;
  G.particles.length = 0; G.wisps.length = 0; G.projectiles.length = 0; G.hazards.length = 0; G.shockwaves.length = 0;
  E.step(1/60, 2);
  G.boss.state = 'chase'; G.boss.cd = 99;
  E.render();
  return { progress: G.progress, boss: G.boss.state, hp: G.boss.hp };
});
console.log(info);
await page.waitForTimeout(300);
await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/boss_clean.jpg', type:'jpeg', quality:90, timeout:60000});
await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/boss_clean_crop.png', clip:{x:390,y:80,width:520,height:420}, timeout:60000});
await browser.close();

